import{_ as i,l as r,o as e,c as l,v as t,p as s,x as n,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"面板构造","description":"","frontmatter":{"title":"面板构造","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/alt-panel-construction.md","filePath":"quant/alt-panel-construction.md","lastUpdated":1789023840000}'),h={name:"quant/alt-panel-construction.md"};function E(u,a,_,m,A,B){const o=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="面板构造" tabindex="-1">面板构造 <a class="header-anchor" href="#面板构造" aria-label="Permalink to &quot;面板构造&quot;">​</a></h1><div class="epigraph"><p>另类观测落在设施、邮编、SKU、船舶上，证券落在 CUSIP 上。面板不是把表格 join 起来，而是声明空间单位、时间单位、映射规则与缺失机制之后，才得到一张可回归的 $(i,t)$。</p><footer>—— 据 Donaldson and Storeygard 对卫星数据空间对齐的讨论；对照资产定价里证券-日期面板的标准构造</footer></div><p><a href="/quant/alt-data-backfill-bias">回填偏差</a>要求 vintage。本课的缺口是：即使每个快照都是当时可得的，观测仍不规则——有的日子有云、有的门店关了、有的公司对应几千个点。要把它们收成与收益对齐的面板，必须写出聚合、映射、缺失与频率转换。后课卫星到特征是本课在影像上的特化；网页合规限制哪些原始观测能进面板。不要把面板当成「数据科学预处理」，它决定你估计的是哪一个经济对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准资产定价面板是证券 \\(i\\)、日期 \\(t\\) 的收益与特征。另类源的原生键是设施 \\(j\\)、网格 \\(g\\)、或文本 ID。映射 \\(j\\to i\\) 多对一，还有一对多（合资、加盟、供应商）。时间上，卫星重访不是交易日，消费数据可能是周，文本是事件时间。硬把最后一次观测前向填充到每个交易日，会制造虚假的日频独立性，也会在缺失非随机时（雨季无影像）造成偏差。</p><p>缺口是三张表：映射表（谁属于哪只证券、权重用营收还是面积）、日历表（观测时刻 → 可交易时刻，含时区与延迟）、缺失表（缺测是无活动还是传感器失败）。没有这三张表，回归里的固定效应不知道在固定什么。</p><h3 id="频率转换会改写信息集" tabindex="-1">频率转换会改写信息集 <a class="header-anchor" href="#频率转换会改写信息集" aria-label="Permalink to &quot;频率转换会改写信息集&quot;">​</a></h3><p>周频消费加总到月，再预测月收益，延迟结构与加总方法（和、均值、期末）会改变。用当周数据预测当周收益，若数据周五才交付，前视。面板的 \\(t\\) 必须是<strong>决策日</strong>，特征值是该日 <code>as_of</code> 下已完成的聚合。这与宏观 nowcast 相同。</p><p><span class="marginnote">权重用今日营收份额去聚合历史门店，是映射上的前视。权重应使用当时已知的披露，例如上年 10-K 的门店数，而不是最新财报往回套。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选定分析单位：通常仍是证券-日，以便接收益。聚合：对 \\(j\\in i\\) 的观测做加权和或中位数，报告有效 \\(j\\) 的个数——覆盖稀疏时特征方差来自抽样而不是来自经济。对齐：观测时间加处理延迟，映射到下一个可交易时刻。缺失：区分结构性零（停车场空）与 NA（云层）；NA 不要填零。共同样本：要求覆盖达到阈值才让 \\(i\\) 进入当日截面，避免早期只有两家门店的「公司」主导排序。</p><p>平衡面板几乎不存在。应用非平衡方法，并报告每个 \\(t\\) 的 \\(N_t\\)。横截面 rank 在 \\(N_t\\) 很小时不稳定，见特征课。公司行为：映射表在分拆、并购日切换，由公司行动引擎提供有效日，不由另类供应商擅自改历史键。</p><h3 id="从面板到可检验假设" tabindex="-1">从面板到可检验假设 <a class="header-anchor" href="#从面板到可检验假设" aria-label="Permalink to &quot;从面板到可检验假设&quot;">​</a></h3><p>构造完成后声明：左边是哪一种收益（持有期 \\(H\\) 与上一课程体制一致），右边是哪一种聚合。停车场车辆数预测的是同店还是营收意外，对象不同。把所有另类列丢进 GBDT，等于拒绝声明对象。面板是假设的载体。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>错误映射把别家的活动算进本公司，制造虚假截面相关，看起来像共同因子。错误填充把天气缺失写成低活动，系统性在旺季低估。错误日历把发布后的修订写进发布前的 \\(t\\)。这三件事都会被回测当成 alpha。正确面板把另类数据降到与点-in-time 基本面相同的纪律，alpha 若还在，才进入容量讨论。</p><p><span class="marginnote">债券没有日度面板那么密。另类若要对齐公司债，左边可能是月度利差变化，映射是发行人而非 CUSIP 条款。不要硬造债券日频面板。</span></p>',17)),(e(),s(c,null,{default:n(()=>[p(o,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20LR%0A%20%20J%5B%22%E5%8E%9F%E7%94%9F%E5%8D%95%E4%BD%8D%20j%2C%20%E6%97%B6%E9%97%B4%20s%22%5D%20--%3E%20MAP%5B%22%E5%BD%93%E6%97%B6%E5%8F%AF%E7%9F%A5%E7%9A%84%20j%E2%86%92i%20%E6%98%A0%E5%B0%84%22%5D%0A%20%20MAP%20--%3E%20AGG%5B%22%E5%8A%A0%E6%9D%83%E8%81%9A%E5%90%88%22%5D%0A%20%20AGG%20--%3E%20CAL%5B%22s%20%2B%20%E5%BB%B6%E8%BF%9F%20%E2%86%92%20%E5%86%B3%E7%AD%96%E6%97%A5%20t%22%5D%0A%20%20CAL%20--%3E%20X%5B%22%E9%9D%A2%E6%9D%BF%20X_it%22%5D%0A%20%20NA%5B%22%E7%BC%BA%E5%A4%B1%E6%9C%BA%E5%88%B6%22%5D%20--%3E%20X%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="覆盖阈值是截面的组成部分" tabindex="-1">覆盖阈值是截面的组成部分 <a class="header-anchor" href="#覆盖阈值是截面的组成部分" aria-label="Permalink to &quot;覆盖阈值是截面的组成部分&quot;">​</a></h3><p>当日有效 \\(j\\) 太少时，特征方差来自抽样。不设阈值，排序会被两家门店的公司主导。阈值使 \\(N_t\\) 变化，这应写入缺失表，而不是事后抱怨因子换手。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>个人级数据即使能提高 \\(R^2\\)，也不应作为面板单位，见合规课。下一课把卫星栅格走到特征，仍使用本课的映射与缺失纪律。不要指望供应商的「公司日表」已经做对——那张表往往是终版回填。</p><p><span class="marginnote">用最新营收份额回算历史门店权重，是映射上的前视。权重只能用当时已披露的结构。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>面板需要映射、日历、缺失三张表，键是决策日的证券。</li><li>前向填充与用最新权重回算历史，都是前视。</li><li>NA 不是零；覆盖阈值决定谁进入当日截面。</li><li>频率转换必须声明聚合与交付延迟。</li><li>映射切换走公司行动有效日。</li><li>出处：Donaldson and Storeygard, <em>Journal of Economic Perspectives</em>, 2016；Henderson, Storeygard and Weil, <em>AER</em>, 2012；点-in-time 与宏观 vintage 传统。</li></ul>',7))])}const b=i(h,[["render",E]]);export{q as __pageData,b as default};
